var VantageAIManager=Classy.newClass();
VantageAIManager.fields({aiId:null,gameController:null,ai:null,storedStates:{}});
VantageAIManager.constructor(function(aiId,config,gameController){this.aiId=aiId;this.gameController=gameController;this.ai=VantageAI.create(aiId,config,gameController);this.reset();});
VantageAIManager.methods({
    getAIId:function(){return this.aiId;},
    getGameId:function(){return this.gameController.getId();},
    update:function(deltaTime){
        try {
            this.ai.update(deltaTime);
            var newInputState=this.ai.getInputState();
            // v5 每帧无条件提交（照 local_patch 原版 AI 驱动）——旧版边缘触发
            // （有变化才交）撞上 rc.setInputState 的静默丢弃（getStarted/maze/
            // tank 未就绪即 return）会把"已提交"记在 storedStates 里，树模式
            // 段内输入恒定 → 丢失后永不再交 → 坦克纹丝不动（主人实测）；
            // 自动模式输入频繁变化自愈所以当年能动。重复提交无害（rc 自带防御）。
            this.gameController.setInputState(newInputState);
            this.storedStates["forward"]=newInputState.getForward();
            this.storedStates["back"]=newInputState.getBack();
            this.storedStates["left"]=newInputState.getLeft();
            this.storedStates["right"]=newInputState.getRight();
            this.storedStates["fire"]=newInputState.getFire();
        } catch(err) {
            console.error('[Vantage] AIManager update 异常:', err);
        }
    },
    shutdown:function(){this.ai.shutdown();},
    reset:function(){
        this.storedStates["forward"]=false;
        this.storedStates["back"]=false;
        this.storedStates["left"]=false;
        this.storedStates["right"]=false;
        this.storedStates["fire"]=false;
        if(this.ai&&this.ai.reset){this.ai.reset();}
    }
});
if(typeof module==='object'){module.exports={VantageAI:VantageAI,VantageAIManager:VantageAIManager};}

